<?php namespace App\Http\Controllers\Api\V1\Ai; use App\Http\Controllers\Controller; use App\Http\Requests\Ai\SendChatMessageRequest; use App\Http\Resources\Ai\AiChatResponseResource; use App\Services\AI\AiChatService; use App\Support\ApiResponse; use App\Models\AiChatConversation; use Illuminate\Support\Facades\Gate; class AiChatController extends Controller { protected $chatService; public function __construct(AiChatService $chatService) { $this->chatService = $chatService; } public function send(SendChatMessageRequest $request) { $user = $request->user(); $conversationId = $request->validated("conversation_id"); if ($conversationId) { $conversation = AiChatConversation::findOrFail($conversationId); Gate::authorize("update", $conversation); } $result = $this->chatService->handleMessage($user, $conversationId, $request->validated("message")); return ApiResponse::success("Message processed successfully", new AiChatResponseResource($result)); } }